# Generated by ekos-lakehouse (RFC 0192). Do not edit: regenerate.
"""Dagster definitions for this pipeline repository: bronze and silver.

One asset per bronze table, built from ../lakehouse.lock.json, which `ekos-lakehouse lakehouse
generate` writes. Each asset runs its table's generated SQL against Trino, then reports the run
to EKOS and reconciles the table against its source; a reconciliation that is not green fails the
asset. EKOS itself never moves a row: this process sends the SQL, Trino moves the data.

Environment:
  EKOS_LH_TRINO_URL       Trino coordinator (default http://127.0.0.1:58080)
  EKOS_LAKEHOUSE_BIN      the ekos-lakehouse binary (default: on PATH)
  EKOS_LH_PROJECT         the EKOS project directory holding ekos.toml (default: ../..)
"""

import json
import os
import subprocess
import time
from pathlib import Path
from urllib.parse import urlparse

import dagster as dg
import trino
from dagster_dbt import DbtCliResource, DbtProject, dbt_assets
import trino.exceptions

HERE = Path(__file__).resolve().parent
REPO = HERE.parent
LOCK = json.loads((REPO / "lakehouse.lock.json").read_text())
SETTINGS = LOCK["settings"]
PROJECT = Path(os.environ.get("EKOS_LH_PROJECT", REPO.parent))
BIN = os.environ.get("EKOS_LAKEHOUSE_BIN", "ekos-lakehouse")


def _connect():
    url = urlparse(os.environ.get("EKOS_LH_TRINO_URL", "http://127.0.0.1:58080"))
    return trino.dbapi.connect(
        host=url.hostname, port=url.port or 8080, http_scheme=url.scheme, user="ekos"
    )


def _run(cur, sql):
    cur.execute(sql)
    return cur.fetchall()


def _statements(text):
    """The statements of a generated file, without the header and trailing `;` (mirrors
    `render::statements`)."""
    out = []
    for part in text.split(";\n"):
        body = "\n".join(l for l in part.splitlines() if not l.startswith("--")).strip()
        body = body.rstrip(";")
        if body:
            out.append(body)
    return out


def _fill(text, run_id, lsn, watermark):
    """Mirrors `render::fill`."""
    q = lambda s: s.replace("'", "''")
    return (
        text.replace("{{run_id}}", q(run_id))
        .replace("{{lsn}}", q(lsn))
        .replace("{{watermark}}", watermark)
    )


def _watermark_literal(value, iceberg_type):
    """Mirrors `render::watermark_literal`."""
    if value is None or value == "":
        return "NULL"
    return "CAST('{}' AS {})".format(value.replace("'", "''"), iceberg_type)


def _ident(name):
    return '"' + name.replace('"', '""') + '"'


STATUS = REPO / ".lakehouse" / "status.json"


def _state(qualified):
    """The table's run-time state from the last `lakehouse sync` (RFC 0194 §5)."""
    try:
        return json.loads(STATUS.read_text()).get(qualified, ["active", None])
    except (FileNotFoundError, json.JSONDecodeError):
        return ["active", None]


def _ekos(*args):
    return subprocess.run(
        [BIN, *args], cwd=PROJECT, capture_output=True, text=True, check=False
    )


def _ensure_namespace(cur, schema):
    """`CREATE SCHEMA IF NOT EXISTS` is not race-safe against an Iceberg REST catalog: assets
    running in parallel lose with "already exists". That answer is the goal reached."""
    for stmt in _statements((REPO / "bronze" / schema / "_namespace.sql").read_text()):
        try:
            _run(cur, stmt)
        except trino.exceptions.TrinoQueryError as e:
            if "already exists" not in str(e):
                raise


def _source_lsn(cur):
    catalog = _ident(SETTINGS["source-catalog"])
    try:
        rows = _run(
            cur,
            f"SELECT * FROM TABLE({catalog}.system.query("
            "query => 'SELECT pg_current_wal_lsn()::text AS lsn'))",
        )
        return rows[0][0]
    except Exception:  # a replica or a role without the function: recorded as unknown
        return ""


@dg.asset(key=["lakehouse", "sync"], group_name="lakehouse")
def sync(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    """Detect source schema changes before any load (RFC 0194): commit safe ones, propose the
    rest. A table added by a safe change gets its asset when the code location reloads."""
    result = _ekos("lakehouse", "sync")
    context.log.info(result.stdout + result.stderr)
    if result.returncode != 0:
        raise dg.Failure(description="lakehouse sync failed", metadata={"output": result.stderr})
    return dg.MaterializeResult(metadata={"sync": dg.MetadataValue.text(result.stdout.strip())})


def _make_asset(table):
    schema, name = table["schema"], table["table"]
    qualified = f"{schema}.{name}"
    base = REPO / "bronze" / schema / name
    mode = table["decision"]["mode"]
    target = ".".join(
        _ident(p) for p in (SETTINGS["target-catalog"], table["namespace"], name)
    )

    @dg.asset(
        name=f"{schema}__{name}",
        key_prefix=["bronze"],
        group_name="bronze",
        deps=[sync],
        description=f"{qualified} → {table['namespace']}.{name} ({mode['mode']})",
    )
    def _load(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        run_id = context.run_id
        state, waiting_on = _state(qualified)
        if state == "paused":
            context.log.warning(f"{qualified} is paused: a schema change waits on {waiting_on}")
            return dg.MaterializeResult(
                metadata={"status": f"paused — waiting on {waiting_on}", "rows_written": 0}
            )
        started = time.monotonic()
        cur = _connect().cursor()
        try:
            _ensure_namespace(cur, schema)
            lsn = _source_lsn(cur)
            watermark = "NULL"
            if mode["mode"] == "incremental":
                for f in ("create.sql", "schema.sql"):
                    for stmt in _statements((base / f).read_text()):
                        _run(cur, stmt)
                wm_type = next(
                    c["iceberg_type"]
                    for c in table["columns"]
                    if c["column"] == mode["watermark"]
                )
                rows = _run(cur, _statements((base / "watermark.sql").read_text())[0])
                watermark = _watermark_literal(rows[0][0], wm_type)
            written = 0
            for f in ("load.sql", "deletes.sql"):
                if (base / f).exists():
                    for stmt in _statements(_fill((base / f).read_text(), run_id, lsn, watermark)):
                        result = _run(cur, stmt)
                        if result and isinstance(result[0][0], int):
                            written += result[0][0]
            snap = _run(
                cur,
                f'SELECT CAST(snapshot_id AS varchar) FROM {target.rsplit(".", 1)[0]}.'
                f'{_ident(name + "$snapshots")} ORDER BY committed_at DESC LIMIT 1',
            )[0][0]
        except Exception as e:
            _ekos("lakehouse", "run-report", "--table", qualified, "--run-id", run_id,
                  "--status", "failed", "--message", str(e)[:500])
            raise
        duration_ms = int((time.monotonic() - started) * 1000)
        _ekos("lakehouse", "run-report", "--table", qualified, "--run-id", run_id,
              "--status", "ok", "--rows", str(written), "--duration-ms", str(duration_ms),
              "--snapshot-id", snap)
        check = _ekos("lakehouse", "reconcile", "--table", qualified, "--run-id", run_id)
        context.log.info(check.stdout + check.stderr)
        if check.returncode != 0:
            raise dg.Failure(
                description=f"{qualified} is not reconciled with its source",
                metadata={"reconcile": dg.MetadataValue.text(check.stdout + check.stderr)},
            )
        return dg.MaterializeResult(
            metadata={
                "rows_written": written,
                "snapshot_id": snap,
                "source_lsn": lsn,
                "reconciliation": dg.MetadataValue.text(check.stdout.strip()),
            }
        )

    return _load


@dg.op
def bronze_maintenance(context: dg.OpExecutionContext):
    """Iceberg maintenance for every bronze table (RFC 0192 §4)."""
    cur = _connect().cursor()
    for table in LOCK["tables"]:
        path = REPO / "bronze" / table["schema"] / table["table"] / "maintenance.sql"
        for stmt in _statements(path.read_text()):
            _run(cur, stmt)
        context.log.info(f"maintained {table['schema']}.{table['table']}")


assets = [sync] + [_make_asset(t) for t in LOCK["tables"]]
resources = {}

# Silver (RFC 0193): the generated dbt project. Its sources carry the bronze asset keys, so each
# model depends on its bronze table; its tests run with the models and fail the run.
DBT_DIR = REPO / "dbt"
if (DBT_DIR / "dbt_project.yml").exists():
    dbt_project = DbtProject(project_dir=DBT_DIR, profiles_dir=DBT_DIR)
    # Always, not only under `dagster dev`: EKOS regenerates the dbt project, so the manifest
    # must follow it, and a one-off `dagster job execute` has none otherwise.
    dbt_project.preparer.prepare(dbt_project)

    @dbt_assets(manifest=dbt_project.manifest_path, project=dbt_project)
    def silver(context: dg.AssetExecutionContext, dbt: DbtCliResource):
        invocation = dbt.cli(["build"], context=context)
        try:
            yield from invocation.stream()
        finally:
            # Every model's build and tests become ledger facts, failed or not (RFC 0196).
            # dagster-dbt gives each invocation its own target directory: read that one, never
            # dbt/target/, which may hold an older run's results (a false green, found by the
            # quickstart test).
            report = _ekos("lakehouse", "run-report", "--run-id", context.run_id,
                           "--dbt-results", str(invocation.target_path))
            context.log.info(report.stdout + report.stderr)
            if report.returncode != 0:
                raise dg.Failure(description="dbt results could not be recorded",
                                 metadata={"output": report.stdout + report.stderr})

    assets.append(silver)
    resources["dbt"] = DbtCliResource(project_dir=dbt_project)


@dg.asset(key=["lakehouse", "health"], group_name="lakehouse",
          deps=[a for a in assets if a is not sync])
def health(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    """After every load and build: alert on state transitions, push metrics (RFC 0196)."""
    alert = _ekos("lakehouse", "alert")
    context.log.info(alert.stdout + alert.stderr)
    metrics = _ekos("lakehouse", "metrics")
    context.log.info(metrics.stdout + metrics.stderr)
    status = _ekos("lakehouse", "status")
    return dg.MaterializeResult(metadata={
        "status": dg.MetadataValue.text(status.stdout.strip().splitlines()[-1] if status.stdout.strip() else ""),
        "alerts": dg.MetadataValue.text(alert.stdout.strip()),
    })


assets.append(health)

# Four loads at a time: the sandbox's measured best (RFC 0190 M0), and gentle on the source.
bronze_job = dg.define_asset_job(
    "bronze",
    selection=dg.AssetSelection.groups("lakehouse", "bronze", "silver"),
    config={"execution": {"config": {"multiprocess": {"max_concurrent": 4}}}},
)


@dg.job
def bronze_maintenance_job():
    bronze_maintenance()


defs = dg.Definitions(
    assets=assets,
    resources=resources,
    jobs=[bronze_job, bronze_maintenance_job],
    schedules=[
        dg.ScheduleDefinition(
            job=bronze_job,
            cron_schedule=SETTINGS["bronze-schedule"],
            default_status=dg.DefaultScheduleStatus.RUNNING,
        ),
        dg.ScheduleDefinition(
            job=bronze_maintenance_job,
            cron_schedule=SETTINGS["maintenance-schedule"],
            default_status=dg.DefaultScheduleStatus.RUNNING,
        ),
    ],
)
